  // ─── Super-admin: Revenue summary ────────────────────────────────────────────
  app.get('/api/admin/revenue-summary', async (req: any, res) => {
    if (!req.isAuthenticated()) return res.sendStatus(401);
    const currentUser = req.user as any;
    if (!currentUser?.isSuperAdmin) return res.status(403).json({ message: 'Super-admin only' });
    try {
      const { rows: activeSubs } = await pool.query(`
        SELECT s.billing_cycle, s.plan_slug, sp.price_monthly, sp.price_yearly
        FROM subscriptions s
        LEFT JOIN subscription_plans sp ON sp.id = s.plan_id
        LEFT JOIN tenants t ON t.id = s.tenant_id
        WHERE s.status = 'active'
          AND s.plan_slug <> 'trial'
          AND t.is_internal IS NOT TRUE
      `);

      let mrr = 0;
      for (const sub of activeSubs) {
        if (sub.billing_cycle === 'yearly' && sub.price_yearly) {
          mrr += Number(sub.price_yearly) / 12;
        } else if (sub.price_monthly) {
          mrr += Number(sub.price_monthly);
        }
      }

      // Plan breakdown
      const planCounts: Record<string, number> = {};
      for (const sub of activeSubs) {
        const slug = sub.plan_slug ?? 'unknown';
        planCounts[slug] = (planCounts[slug] || 0) + 1;
      }

      res.json({
        mrr: Math.round(mrr),
        arr: Math.round(mrr * 12),
        activePayingCount: activeSubs.length,
        planCounts,
      });
    } catch (err) {
      console.error('[ADMIN] GET /api/admin/revenue-summary error:', err);
      res.status(500).json({ message: 'Failed to fetch revenue summary' });
    }
  });

  // ─── Super-admin: Create tenant manually ──────────────────────────────────────
  app.post('/api/admin/tenants', async (req: any, res) => {
    if (!req.isAuthenticated()) return res.sendStatus(401);
    const currentUser = req.user as any;
    if (!currentUser?.isSuperAdmin) return res.status(403).json({ message: 'Super-admin only' });
    const { name, slug, plan, adminUsername, adminPassword, adminEmail, maxUsers, trialDays, industry, country_code } = req.body;
    if (!name || !slug || !adminUsername || !adminPassword) {
      return res.status(400).json({ message: 'name, slug, adminUsername, adminPassword are required' });
    }
    try {
      // Pre-validate slug uniqueness
      const [existingSlug] = await db.select({ id: tenants.id }).from(tenants).where(eq(tenants.slug, slug));
      if (existingSlug) return res.status(409).json({ message: `Slug "${slug}" is already taken` });

      // Pre-validate username uniqueness (check globally and per-tenant-id)
      const existingUsers = await db.select({ id: users.id }).from(users).where(eq(users.username, adminUsername));
      if (existingUsers.length > 0) {
        return res.status(409).json({ message: `Username "${adminUsername}" is already taken. Please choose a different admin username.` });
      }

      const VALID_PLAN_SLUGS = ['restaurant', 'hotel', 'healthcare', 'pharmacy', 'retail', 'trial', 'enterprise', 'crm', 'agriculture', 'education', 'logistics', 'ngo', 'real_estate'];
      const planSlug = plan && VALID_PLAN_SLUGS.includes(plan) ? plan : 'trial';
      if (plan && !VALID_PLAN_SLUGS.includes(plan)) {
        console.warn(`[TENANT SETUP] Unknown plan slug "${plan}", defaulting to trial`);
      }
      const [planRow] = await db.select().from(subscriptionPlans).where(eq(subscriptionPlans.slug, planSlug));
      const trialEnd = trialDays ? new Date(Date.now() + parseInt(trialDays) * 24 * 60 * 60 * 1000).toISOString() : null;

      // Hash password before transaction (async work outside tx is safer)
      const { hashPassword } = await import('./auth');
      const hashed = await hashPassword(adminPassword);

      // Auto-lookup country details if country_code provided
      let countryFields: Record<string, string> = {};
      if (country_code) {
        try {
          const cRows = await db.execute(sql`
            SELECT currency_code, currency_symbol, timezone, tax_regime, date_format
            FROM countries WHERE country_code = ${country_code} LIMIT 1
          `);
          const cr = (cRows.rows as any[])[0];
          if (cr) {
            countryFields = {
              country_code,
              currency_code:   cr.currency_code   ?? 'INR',
              currency_symbol: cr.currency_symbol ?? '₹',
              timezone:        cr.timezone        ?? 'Asia/Kolkata',
              tax_regime:      cr.tax_regime      ?? 'GST',
              date_format:     cr.date_format     ?? 'DD/MM/YYYY',
            };
          }
        } catch { /* countries table may not exist — skip gracefully */ }
      }

      // Wrap everything in a transaction so partial failures don't leave orphaned tenants
      const result = await db.transaction(async (tx) => {
        // Create tenant
        const [newTenant] = await tx.insert(tenants).values({
          name,
          slug,
          plan: planSlug,
          status: planSlug === 'trial' ? 'trial' : 'active',
          maxUsers: maxUsers ?? planRow?.maxUsers ?? 5,
          billingEmail: adminEmail ?? null,
          trialEndsAt: trialEnd,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          ...(industry ? { industry } : {}),
          ...countryFields,
        } as any).returning();

        // Create subscription
        const [newSub] = await tx.insert(subscriptions).values({
          tenantId: newTenant.id,
          planId: planRow?.id ?? null,
          planSlug,
          billingCycle: planSlug === 'trial' ? 'trial' : 'monthly',
          status: planSlug === 'trial' ? 'trial' : 'active',
          startedAt: new Date().toISOString(),
          currentPeriodStart: new Date().toISOString(),
          currentPeriodEnd: trialEnd,
        }).returning();

        // Seed default roles FIRST so we can assign the admin role to the user
        const defaultRoles = ['admin', 'manager', 'operator', 'reviewer', 'accountsmanager'];
        for (const roleName of defaultRoles) {
          await tx.execute(sql`
            INSERT INTO roles (name, tenant_id, description)
            SELECT ${roleName}, ${newTenant.id}, ${'Default ' + roleName + ' role'}
            WHERE NOT EXISTS (
              SELECT 1 FROM roles WHERE name = ${roleName} AND tenant_id = ${newTenant.id}
            )
          `);
        }

        // Fetch the admin role ID for this tenant
        const adminRoleRows = await tx.execute(sql`
          SELECT id FROM roles WHERE name = 'admin' AND tenant_id = ${newTenant.id} LIMIT 1
        `);
        const adminRoleId = (adminRoleRows.rows?.[0] as any)?.id ?? null;

        // Create admin user with the admin role assigned
        const [newUser] = await tx.insert(users).values({
          username: adminUsername,
          email: adminEmail ?? null,
          password: hashed,
          tenantId: newTenant.id,
          roleId: adminRoleId,
        } as any).returning();

        // Also insert into user_roles junction table for multi-role support
        if (adminRoleId && newUser?.id) {
          await tx.execute(sql`
            INSERT INTO user_roles (user_id, role_id, tenant_id)
            VALUES (${newUser.id}, ${adminRoleId}, ${newTenant.id})
            ON CONFLICT (user_id, role_id) DO NOTHING
          `);
        }

        // Log billing event
        await tx.insert(billingEvents).values({
          tenantId: newTenant.id,
          subscriptionId: newSub.id,
          eventType: 'plan_activated',
          fromPlan: null,
          toPlan: planSlug,
          billingCycle: planSlug === 'trial' ? 'trial' : 'monthly',
          amount: 0,
          notes: `Tenant created manually by super-admin ${currentUser.username}`,
          createdBy: currentUser.username,
        });

        return { newTenant, newSub, adminRoleId, adminUserId: newUser?.id };
      });

      // Seed role permissions outside the transaction (non-critical, can fail independently)
      try {
        const seedResult = await seedTenantPermissions(result.newTenant.id);
        console.log(`[TENANT SETUP] Seeded ${seedResult.inserted} permission rows for tenant ${result.newTenant.id}`);
      } catch (seedErr: any) {
        console.error(`[TENANT SETUP] Permission seeding failed (non-fatal):`, seedErr.message);
      }

      res.json({ message: 'Tenant created successfully', tenant: result.newTenant });
    } catch (err: any) {
      console.error('POST /api/admin/tenants error:', err);
      // Provide friendly messages for known constraint violations
      if (err.code === '23505') {
        if (err.constraint?.includes('username')) {
          return res.status(409).json({ message: `Username "${adminUsername}" is already taken. Please choose a different admin username.` });
        }
        if (err.constraint?.includes('slug') || err.detail?.includes('slug')) {
          return res.status(409).json({ message: `Slug "${slug}" is already taken.` });
        }
      }
      res.status(500).json({ message: err.message ?? 'Failed to create tenant' });
    }
  });

