  // Get scrap inventory summary/report for month-end loss calculation (manager+ only)
  app.get('/api/scrap-inventory/report', requireRole('admin', 'manager', 'accountsmanager'), async (req: any, res) => {
    try {
      const { month, year } = req.query;
      
      // Default to current month/year if not provided
      const targetMonth = month ? parseInt(month as string) : new Date().getMonth() + 1;
      const targetYear = year ? parseInt(year as string) : new Date().getFullYear();
      
      // Get scrap records for the month
      const startDate = new Date(targetYear, targetMonth - 1, 1);
      const endDate = new Date(targetYear, targetMonth, 0, 23, 59, 59);
      
      const scrapRecords = await db.select()
        .from(scrapInventory)
        .where(and(
          eq(scrapInventory.recordStatus, 1), tc(scrapInventory),
          gte(scrapInventory.scrapDate, startDate.toISOString()),
          lte(scrapInventory.scrapDate, endDate.toISOString())
        ))
        .orderBy(desc(scrapInventory.scrapDate));
      
      // Calculate summary
      const summary = {
        totalRecords: scrapRecords.length,
        totalQuantity: scrapRecords.reduce((sum, r) => sum + r.quantity, 0),
        totalCostValue: scrapRecords.reduce((sum, r) => sum + (r.totalCostValue || 0), 0),
        totalSellingValue: scrapRecords.reduce((sum, r) => sum + (r.totalSellingValue || 0), 0),
        totalLossAmount: scrapRecords.reduce((sum, r) => sum + (r.lossAmount || 0), 0),
        totalGstReversal: scrapRecords.reduce((sum, r) => sum + (r.gstReversal || 0), 0),
        totalDisposalValue: scrapRecords.reduce((sum, r) => sum + (r.disposalValue || 0), 0),
        netLoss: 0, // Will be calculated
        byApprovalStatus: {
          pending: scrapRecords.filter(r => r.approvalStatus === 'pending').length,
          approved: scrapRecords.filter(r => r.approvalStatus === 'approved').length,
          rejected: scrapRecords.filter(r => r.approvalStatus === 'rejected').length,
        },
        byDamageReason: {} as Record<string, { count: number, lossAmount: number }>,
        byProduct: {} as Record<string, { productName: string, count: number, quantity: number, lossAmount: number }>,
      };
      
      // Net loss = total cost value - disposal recovery
      summary.netLoss = summary.totalLossAmount - summary.totalDisposalValue;
      
      // Group by damage reason
      scrapRecords.forEach(r => {
        const reason = r.damageReason || 'other';
        if (!summary.byDamageReason[reason]) {
          summary.byDamageReason[reason] = { count: 0, lossAmount: 0 };
        }
        summary.byDamageReason[reason].count++;
        summary.byDamageReason[reason].lossAmount += r.lossAmount || 0;
      });
      
      // Group by product
      scrapRecords.forEach(r => {
        const productId = r.productId;
        if (!summary.byProduct[productId]) {
          summary.byProduct[productId] = { productName: r.productName, count: 0, quantity: 0, lossAmount: 0 };
        }
        summary.byProduct[productId].count++;
        summary.byProduct[productId].quantity += r.quantity;
        summary.byProduct[productId].lossAmount += r.lossAmount || 0;
      });
      
      res.json({
        month: targetMonth,
        year: targetYear,
        summary,
        records: scrapRecords,
      });
    } catch (error) {
      console.error("Error generating scrap report:", error);
      res.status(500).json({ message: "Failed to generate scrap report" });
    }
  });

  // Get sales returns summary report with disposition breakdown
  app.get('/api/reports/sales-returns-summary', requireRole('admin', 'manager', 'accountsmanager'), async (req: any, res) => {
    try {
      const { month, year, dateFrom, dateTo } = req.query;
      
      let startDate: Date;
      let endDate: Date;
      
      if (dateFrom && dateTo) {
        startDate = new Date(dateFrom as string);
        endDate = new Date(dateTo as string);
        endDate.setHours(23, 59, 59, 999);
      } else {
        const targetMonth = month ? parseInt(month as string) : new Date().getMonth() + 1;
        const targetYear = year ? parseInt(year as string) : new Date().getFullYear();
        startDate = new Date(targetYear, targetMonth - 1, 1);
        endDate = new Date(targetYear, targetMonth, 0, 23, 59, 59);
      }
      
      // Get all sales returns in the date range
      const returns = await db.select()
        .from(salesReturns)
        .where(and(
          eq(salesReturns.recordStatus, 1), tc(salesReturns),
          gte(salesReturns.returnDate, startDate.toISOString()),
          lte(salesReturns.returnDate, endDate.toISOString())
        ))
        .orderBy(desc(salesReturns.returnDate));
      
      // Get all return items for these returns
      const returnIds = returns.map(r => r.id);
      let allItems: any[] = [];
      
      if (returnIds.length > 0) {
        allItems = await db.select({
          id: salesReturnItems.id,
          returnId: salesReturnItems.returnId,
          productId: salesReturnItems.productId,
          quantityReturned: salesReturnItems.quantityReturned,
          disposition: salesReturnItems.disposition,
          creditAmount: salesReturnItems.creditAmount,
          productName: products.productName,
        })
        .from(salesReturnItems)
        .leftJoin(products, eq(salesReturnItems.productId, products.id))
        .where(inArray(salesReturnItems.returnId, returnIds));
      }
      
      // Calculate summary
      const summary = {
        totalReturns: returns.length,
        totalItems: allItems.length,
        totalQuantityReturned: allItems.reduce((sum, r) => sum + (r.quantityReturned || 0), 0),
        totalCreditAmount: allItems.reduce((sum, r) => sum + (r.creditAmount || 0), 0),
        byStatus: {
          pending: returns.filter(r => r.status === 'pending').length,
          received: returns.filter(r => r.status === 'received').length,
          inspected: returns.filter(r => r.status === 'inspected').length,
          completed: returns.filter(r => r.status === 'completed').length,
        },
        byDisposition: {
          restock: { count: 0, quantity: 0 },
          scrap: { count: 0, quantity: 0 },
          repack: { count: 0, quantity: 0 },
          pending: { count: 0, quantity: 0 },
        } as Record<string, { count: number; quantity: number }>,
        byProduct: {} as Record<string, { productName: string; quantity: number; creditAmount: number }>,
      };
      
      // Group by disposition
      allItems.forEach(item => {
        const disposition = item.disposition || 'pending';
        if (!summary.byDisposition[disposition]) {
          summary.byDisposition[disposition] = { count: 0, quantity: 0 };
        }
        summary.byDisposition[disposition].count++;
        summary.byDisposition[disposition].quantity += item.quantityReturned || 0;
        
        // Group by product
        const productId = item.productId;
        if (!summary.byProduct[productId]) {
          summary.byProduct[productId] = { productName: item.productName || 'Unknown', quantity: 0, creditAmount: 0 };
        }
        summary.byProduct[productId].quantity += item.quantityReturned || 0;
        summary.byProduct[productId].creditAmount += item.creditAmount || 0;
      });
      
      // Get customer names for returns
      const vendorIds = [...new Set(returns.map(r => r.vendorId).filter(Boolean))];
      let vendorMap: Record<string, string> = {};
      if (vendorIds.length > 0) {
        const vendorData = await db.select({ id: vendors.id, name: vendors.name })
          .from(vendors)
          .where(inArray(vendors.id, vendorIds as string[]));
        vendorData.forEach(v => { vendorMap[v.id] = v.name; });
      }
      
      // Enhance return records with customer name
      const returnsWithDetails = returns.map(r => ({
        ...r,
        customerName: r.vendorId ? vendorMap[r.vendorId] || 'Unknown' : 'Unknown',
        items: allItems.filter(item => item.returnId === r.id),
      }));
      
      res.json({
        dateFrom: startDate.toISOString(),
        dateTo: endDate.toISOString(),
        summary,
        records: returnsWithDetails,
      });
    } catch (error) {
      console.error("Error generating sales returns summary:", error);
      res.status(500).json({ message: "Failed to generate sales returns summary" });
    }
  });

  // Get repacking report with date range filtering
