  // Create new customer advance
  app.post('/api/customer-advances', requireRole('admin', 'manager', 'accountsmanager'), async (req: any, res) => {
    try {
      const isPrepayment = req.body.advanceType === 'prepayment';
      const numberPrefix = isPrepayment ? 'PRE' : 'ADV';
      
      // Generate advance number
      const today = format(new Date(), 'yyyyMMdd');
      const existingCount = await db.select({ count: sql<number>`count(*)` })
        .from(customerAdvances)
        .where(sql`${customerAdvances.advanceNumber} LIKE ${numberPrefix + '-' + today + '%'}`);
      const seq = (existingCount[0]?.count || 0) + 1;
      const advanceNumber = `${numberPrefix}-${today}-${String(seq).padStart(3, '0')}`;
      
      const validatedData = insertCustomerAdvanceSchema.parse({
        ...req.body,
        receivedBy: req.user?.id,
        advanceType: isPrepayment ? 'prepayment' : 'security_deposit',
      });
      
      const [created] = await db.insert(customerAdvances).values({
        ...validatedData,
        advanceNumber,
        usedAmount: 0,
        status: 'active',
      }).returning();
      
      await logAudit(req.user?.id, 'CREATE', 'customer_advances', created.id, 
        `Created advance ${advanceNumber} for ₹${(created.amount / 100).toFixed(2)}`);
      
      res.json({ advance: created, message: "Advance payment recorded successfully" });
      
      // Auto-generate journal entry (non-blocking)
      try {
        const vendor = await storage.getVendor(created.vendorId);
        const { journalForCustomerAdvance } = await import('./journal-service');
        await journalForCustomerAdvance(created, vendor?.vendorName || 'Unknown');
      } catch (je) { console.error('[JOURNAL] Customer advance auto-entry failed:', je); }
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ message: "Invalid data", errors: error.errors });
      }
      console.error("Error creating customer advance:", error);
      res.status(500).json({ message: "Failed to create customer advance" });
    }
  });

  // Apply advance to invoice
  app.post('/api/customer-advances/:id/apply', requireRole('admin', 'manager', 'accountsmanager'), async (req: any, res) => {
    try {
      const { id } = req.params;
      const { invoiceId, amount, remarks } = req.body;
      
      if (!invoiceId || !amount) {
        return res.status(400).json({ message: "Invoice ID and amount are required" });
      }
      
      const amountPaise = parseInt(amount);
      if (isNaN(amountPaise) || amountPaise <= 0) {
        return res.status(400).json({ message: "Amount must be a positive number" });
      }
      
      // Use transaction for atomicity
      const result = await db.transaction(async (tx) => {
        // Get advance with lock
        const [advance] = await tx.select().from(customerAdvances)
          .where(and(eq(customerAdvances.id, id), eq(customerAdvances.recordStatus, 1), tc(customerAdvances)))
          .for('update');
        
        if (!advance) {
          throw new Error("Advance not found");
        }
        
        if (advance.status === 'cancelled') {
          throw new Error("Cannot apply cancelled advance");
        }
        
        const availableBalance = advance.amount - advance.usedAmount;
        if (amountPaise > availableBalance) {
          throw new Error(`Insufficient advance balance. Available: ₹${(availableBalance / 100).toFixed(2)}`);
        }
        
        // Get invoice
        const [invoice] = await tx.select().from(invoices)
          .where(eq(invoices.id, invoiceId));
        
        if (!invoice) {
          throw new Error("Invoice not found");
        }
        
        // Check invoice belongs to same vendor family by buyerName matching
        const allVendors = await storage.getAllVendors();
        const advanceVendor = allVendors.find(v => v.id === advance.vendorId);
        if (!advanceVendor) {
          throw new Error("Advance vendor not found");
        }
        
        // Build family: the advance vendor + its children + its parent + siblings under same parent
        const familyNames: string[] = [advanceVendor.vendorName];
        
        // Add children of advance vendor
        const children = allVendors.filter(v => v.parentVendorId === advance.vendorId);
        familyNames.push(...children.map(c => c.vendorName));
        
        // If advance vendor has a parent, add parent and all its children (siblings)
        if (advanceVendor.parentVendorId) {
          const parent = allVendors.find(v => v.id === advanceVendor.parentVendorId);
          if (parent) {
            familyNames.push(parent.vendorName);
            const siblings = allVendors.filter(v => v.parentVendorId === parent.id && v.id !== advance.vendorId);
            familyNames.push(...siblings.map(s => s.vendorName));
          }
        }
        
        const buyerName = invoice.buyerName?.trim().toLowerCase() || '';
        const isFamilyMatch = familyNames.some(name => name.trim().toLowerCase() === buyerName);
        
        if (!isFamilyMatch) {
          throw new Error("Invoice does not belong to the same customer family as the advance");
        }
        
        // Create payment record
        const [payment] = await tx.insert(invoicePayments).values({
          invoiceId,
          paymentDate: new Date().toISOString(),
          amount: amountPaise,
          paymentMethod: 'Advance',
          paymentType: 'Advance',
          referenceNumber: advance.advanceNumber,
          bankName: null,
          remarks: remarks || `Applied from advance ${advance.advanceNumber}`,
          recordedBy: req.user?.id,
        }).returning();
        
        // Create application record
        const [application] = await tx.insert(advanceApplications).values({
          advanceId: id,
          invoiceId,
          invoicePaymentId: payment.id,
          appliedAmount: amountPaise,
          applicationDate: format(new Date(), 'yyyy-MM-dd'),
          appliedBy: req.user?.id,
          remarks,
        }).returning();
        
        // Update advance used amount
        const newUsedAmount = advance.usedAmount + amountPaise;
        const newStatus = newUsedAmount >= advance.amount ? 'fully_used' : 'active';
        
        await tx.update(customerAdvances)
          .set({ 
            usedAmount: newUsedAmount, 
            status: newStatus,
            updatedAt: new Date().toISOString(),
          })
          .where(eq(customerAdvances.id, id));
        
        return { payment, application, advance };
      });
      
      await logAudit(req.user?.id, 'CREATE', 'advance_applications', result.application.id,
        `Applied ₹${(amountPaise / 100).toFixed(2)} from advance ${result.advance.advanceNumber} to invoice ${invoiceId}`);
      
      res.json({ 
        application: result.application, 
        payment: result.payment,
        message: "Advance applied successfully" 
      });
      
      // Auto-generate journal entry (non-blocking)
      try {
        const { journalForAdvanceApplication } = await import('./journal-service');
        const inv = await storage.getInvoice(invoiceId);
        const vendor = await storage.getVendor(result.advance.vendorId);
        await journalForAdvanceApplication(result.application, result.advance, inv, vendor?.vendorName || 'Unknown');
      } catch (je) { console.error('[JOURNAL] Advance application auto-entry failed:', je); }
    } catch (error) {
      if (error instanceof Error) {
        return res.status(400).json({ message: error.message });
      }
      console.error("Error applying advance:", error);
      res.status(500).json({ message: "Failed to apply advance" });
    }
  });

  // Cancel customer advance
  app.post('/api/customer-advances/:id/cancel', requireRole('admin'), async (req: any, res) => {
    try {
      const { id } = req.params;
      const { remarks } = req.body;
      
      const [advance] = await db.select().from(customerAdvances)
        .where(and(eq(customerAdvances.id, id), eq(customerAdvances.recordStatus, 1), tc(customerAdvances)));
      
      if (!advance) {
        return res.status(404).json({ message: "Advance not found" });
      }

      // Check for active (non-cancelled) invoice applications
      // If usedAmount > 0 but all applications are on cancelled invoices, we can still cancel
      if (advance.usedAmount > 0) {
        const activeApplications = await db
          .select({ id: advanceApplications.id })
          .from(advanceApplications)
          .innerJoin(invoices, eq(advanceApplications.invoiceId, invoices.id))
          .where(and(
            eq(advanceApplications.advanceId, id),
            eq(advanceApplications.recordStatus, 1),
            ne(invoices.status, 'cancelled')
          ));
        if (activeApplications.length > 0) {
          return res.status(400).json({
            message: "Cannot cancel advance that has been applied to active invoices. Remove advance applications first."
          });
        }
        // All applications are on cancelled invoices — safe to cancel; reset usedAmount
      }

      const [updated] = await db.update(customerAdvances)
        .set({
          status: 'cancelled',
          usedAmount: 0,
          cancelledAt: new Date().toISOString(),
          cancellationRemarks: remarks,
          cancelledBy: req.user?.id,
          updatedAt: new Date().toISOString(),
        })
        .where(eq(customerAdvances.id, id))
        .returning();
      
      await logAudit(req.user?.id, 'UPDATE', 'customer_advances', id, 
        `Cancelled advance ${advance.advanceNumber}`);
      
      res.json({ advance: updated, message: "Advance cancelled successfully" });

      // Reverse the journal entry for this advance (non-blocking)
      try {
        const existingJournal = await storage.getJournalEntryBySource('customer_advance', id);
        if (existingJournal) {
          await storage.deleteJournalEntry(existingJournal.id);
          console.log(`[JOURNAL] Reversed customer advance journal for advance ${id} (${advance.advanceNumber})`);
        }
      } catch (journalError) {
        console.error('[JOURNAL] Non-blocking error reversing advance journal on cancel:', journalError);
      }
    } catch (error) {
      console.error("Error cancelling advance:", error);
      res.status(500).json({ message: "Failed to cancel advance" });
    }
  });

