  // POST /api/external-api-catalogue — register a custom API definition
  app.post('/api/external-api-catalogue', isAuthenticated, requireRole('admin', 'manager'), async (req: any, res) => {
    try {
      const tenantId: number = req.session?.tenantId ?? req.user?.tenantId ?? 1;
      const { method, path: apiPath, label, description, category, params, module: apiModule } = req.body;
      if (!method || !apiPath || !label) {
        return res.status(400).json({ message: 'method, path, and label are required' });
      }
      const validMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'];
      if (!validMethods.includes(method.toUpperCase())) {
        return res.status(400).json({ message: `method must be one of: ${validMethods.join(', ')}` });
      }
      // Generate a stable api_id from label
      const apiId = label.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '') + '_' + Date.now();
      await db.execute(sql`
        INSERT INTO external_api_definitions
          (tenant_id, api_id, method, path, label, description, category, params, module, is_active, created_by, created_at)
        VALUES
          (${tenantId}, ${apiId}, ${method.toUpperCase()}, ${apiPath.trim()},
           ${label.trim()}, ${description?.trim() ?? null}, ${category?.trim() ?? 'Custom'},
           ${JSON.stringify(params ?? [])}, ${apiModule ?? null}, 1, ${req.user?.id ?? null}, NOW())
      `);
      const [created] = await db.execute(sql`
        SELECT * FROM external_api_definitions WHERE api_id = ${apiId} AND tenant_id = ${tenantId} LIMIT 1
      `).then(r => r.rows as any[]);
      res.json({ ...created, isCustom: true });
    } catch (err) {
      console.error('[Catalogue] Create error:', err);
      res.status(500).json({ message: 'Failed to register API' });
    }
  });

  // DELETE /api/external-api-catalogue/:apiId — remove a custom API definition
  app.delete('/api/external-api-catalogue/:apiId', isAuthenticated, requireRole('admin'), async (req: any, res) => {
    try {
      const tenantId: number = req.session?.tenantId ?? req.user?.tenantId ?? 1;
      await db.execute(sql`
        UPDATE external_api_definitions SET is_active = 0
        WHERE api_id = ${req.params.apiId} AND tenant_id = ${tenantId}
      `);
      res.json({ message: 'API definition removed' });
    } catch (err) {
      console.error('[Catalogue] Delete error:', err);
      res.status(500).json({ message: 'Failed to remove API definition' });
    }
  });

  // GET /api/external/param-suggestions — returns autocomplete hint values for known parameter types
  // Supports: customer, vendor, sku, item, transporter
  app.get('/api/external/param-suggestions', isAuthenticated, async (req: any, res) => {
    try {
      const tenantId: number = req.session?.tenantId ?? req.user?.tenantId ?? 1;
      const type = (req.query.type as string ?? '').toLowerCase();
      let suggestions: string[] = [];

      if (type === 'customer' || type === 'buyer') {
        const rows = await db.execute(sql`
          SELECT DISTINCT buyer_name AS name
          FROM invoices
          WHERE tenant_id = ${tenantId} AND record_status = 1 AND buyer_name IS NOT NULL AND buyer_name <> ''
          ORDER BY name
          LIMIT 100
        `);
        suggestions = (rows.rows as any[]).map(r => r.name).filter(Boolean);
      } else if (type === 'vendor') {
        const rows = await db.execute(sql`
          SELECT vendor_name AS name FROM vendors
          WHERE tenant_id = ${tenantId} AND record_status = 1
          ORDER BY name LIMIT 100
        `);
        suggestions = (rows.rows as any[]).map(r => r.name).filter(Boolean);
      } else if (type === 'sku' || type === 'item' || type === 'material') {
        const rows = await db.execute(sql`
          SELECT material_name AS name FROM raw_materials
          WHERE tenant_id = ${tenantId} AND record_status = 1
          ORDER BY name LIMIT 100
        `);
        suggestions = (rows.rows as any[]).map(r => r.name).filter(Boolean);
      } else if (type === 'transporter') {
        const rows = await db.execute(sql`
          SELECT transporter_name AS name FROM transporters
          WHERE tenant_id = ${tenantId}
          ORDER BY name LIMIT 50
        `);
        suggestions = (rows.rows as any[]).map(r => r.name).filter(Boolean);
      }

      res.json({ type, suggestions });
    } catch (err) {
      console.error('[ParamSuggestions] Error:', err);
      res.json({ type: req.query.type ?? '', suggestions: [] });
    }
  });

  // POST /api/external-api-keys  — create a new key (returns raw key ONCE)
  // Accepts optional: scopes (string[] of API IDs), description (string)
  app.post('/api/external-api-keys', isAuthenticated, requireRole('admin', 'manager'), async (req: any, res) => {
    try {
      const { name, scopes, description } = req.body;
      if (!name?.trim()) return res.status(400).json({ message: 'Key name is required' });

      // Validate scopes — must be valid API IDs or null (= all access)
      const validIds = EXTERNAL_API_CATALOGUE.map(a => a.id);
      let scopesJson: string | null = null;
      if (Array.isArray(scopes) && scopes.length > 0) {
        const invalid = scopes.filter((s: string) => !validIds.includes(s));
        if (invalid.length > 0) return res.status(400).json({ message: `Invalid scope(s): ${invalid.join(', ')}` });
        scopesJson = JSON.stringify(scopes);
      }

      const tenantId: number = req.session?.tenantId ?? req.user?.tenantId ?? 1;
      const rawKey = `kinto_${crypto.randomBytes(32).toString('hex')}`;
      const keyHash = crypto.createHash('sha256').update(rawKey).digest('hex');

      await db.execute(sql`
        INSERT INTO external_api_keys (tenant_id, name, key_hash, is_active, created_by, scopes, description)
        VALUES (${tenantId}, ${name.trim()}, ${keyHash}, 1, ${req.user?.id ?? null},
                ${scopesJson}, ${description?.trim() ?? null})
      `);

      const [record] = await db.execute(sql`
        SELECT id, name, created_at FROM external_api_keys
        WHERE key_hash = ${keyHash} AND tenant_id = ${tenantId}
        LIMIT 1
      `).then(r => r.rows as any[]);

      res.json({
        id: record.id,
        name: record.name,
        scopes: scopes ?? null,
        createdAt: record.created_at,
        rawKey,
        message: 'Save this key securely — it will not be shown again.',
      });
    } catch (err) {
      console.error('[API Keys] Create error:', err);
      res.status(500).json({ message: 'Failed to create API key' });
    }
  });

  // GET /api/external-api-keys — list all keys for this tenant
  app.get('/api/external-api-keys', isAuthenticated, requireRole('admin', 'manager'), async (req: any, res) => {
    try {
      const tenantId: number = req.session?.tenantId ?? req.user?.tenantId ?? 1;
      const rows = await db.execute(sql`
        SELECT id, name, is_active, created_by, created_at, last_used_at, scopes, description
        FROM external_api_keys
        WHERE tenant_id = ${tenantId}
        ORDER BY created_at ASC
      `);
      const keys = (rows.rows as any[]).map(k => ({
        id: k.id,
        name: k.name,
        isActive: k.is_active,
        createdBy: k.created_by,
        createdAt: k.created_at,
        lastUsedAt: k.last_used_at,
        scopes: k.scopes ? JSON.parse(k.scopes) : null,
        description: k.description,
      }));
      res.json(keys);
    } catch (err) {
      console.error('[API Keys] List error:', err);
      res.status(500).json({ message: 'Failed to fetch API keys' });
    }
  });

  // DELETE /api/external-api-keys/:id — revoke a key
  app.delete('/api/external-api-keys/:id', isAuthenticated, requireRole('admin'), async (req: any, res) => {
    try {
      const tenantId: number = req.session?.tenantId ?? req.user?.tenantId ?? 1;
      await db.update(externalApiKeys)
        .set({ isActive: 0 })
        .where(and(eq(externalApiKeys.id, req.params.id), eq(externalApiKeys.tenantId, tenantId)));
      res.json({ message: 'Key revoked' });
    } catch (err) {
      console.error('[API Keys] Revoke error:', err);
      res.status(500).json({ message: 'Failed to revoke API key' });
    }
  });

  // ─── External REST API — Customer Outstanding ───────────────────────────────
  // GET /api/external/customer-outstanding
  // Authorization: Bearer <api_key>
  //
  // Outstanding Calculation (mirrors the in-app Vendor Ledger formula):
  //   For each vendor family (parent + children):
  //     1. Match ALL invoices where buyer_name OR ship_to_name matches any vendor name in family
  //     2. Load invoice_payments for those invoices (actual cash / DN adjustments)
  //     3. Per invoice: outstanding = total_amount + debit_notes - credit_notes - SUM(invoice_payments)
  //     4. Load customer advances and reduce from total
  //     5. Net balance = totalInvoiced + totalDebitNotes - totalCreditNotes
  //                      - actualPayments - dnAdjustments - advances
  //
  //   This matches the Vendor Ledger "Current Balance" exactly.
  //
  // Business Rules (applied to the invoice breakdown list):
  //   COD vendor        → include ALL outstanding invoices
  //   Bill-to-Bill      → exclude latest (most recent) outstanding invoice
  //   Bill-to-Bill with ANY outstanding invoice > 30 days old → include ALL
  //
  // Parent-Child vendor roll-up:
  //   Child vendors are pooled under the parent.
  //   `hasChildren`, `childAccountNames`, `sourceAccount` per invoice indicate origin.
  //
  // HP Retail (HPCL) customers: `isHpRetail: true` + `shippingAddress` object.
  //
  // Response amounts are in RUPEES (paise ÷ 100, 2 dp)
  app.get('/api/external/customer-outstanding', async (req: any, res) => {
    try {
      const _co_start = Date.now();
      let _co_keyId: string | undefined;
      // ── 1. Authenticate — accept Bearer token (external) OR authenticated session (internal UI) ──
      let tenantId: number;
      const authHeader = req.headers['authorization'] || '';
      const rawKey = authHeader.startsWith('Bearer ') ? authHeader.slice(7).trim() : '';

      if (rawKey) {
        const keyHash = crypto.createHash('sha256').update(rawKey).digest('hex');
        const keyRows = await db.execute(sql`
          SELECT id, tenant_id, scopes FROM external_api_keys
          WHERE key_hash = ${keyHash} AND is_active = 1 LIMIT 1
        `);
        const keyRecord = (keyRows.rows as any[])[0];
        if (!keyRecord) {
          return res.status(401).json({ error: 'Unauthorized', message: 'Invalid or revoked API key' });
        }
        const keyScopes: string[] | null = keyRecord.scopes ? JSON.parse(keyRecord.scopes) : null;
        if (keyScopes && !keyScopes.includes('customer_outstanding')) {
          return res.status(403).json({ error: 'Forbidden', message: 'This API key does not have access to customer_outstanding. Update the key scopes in API Keys settings.' });
        }
        db.execute(sql`UPDATE external_api_keys SET last_used_at = NOW() WHERE id = ${keyRecord.id}`).catch(() => {});
        tenantId = keyRecord.tenant_id;
        _co_keyId = String(keyRecord.id);
      } else if (req.isAuthenticated && req.isAuthenticated()) {
        tenantId = req.user?.tenantId;
        if (!tenantId) return res.status(401).json({ error: 'Unauthorized' });
      } else {
        return res.status(401).json({ error: 'Unauthorized', message: 'Missing Authorization: Bearer <key> header' });
      }

      // Register call-logging on response finish (fires after headers are sent)
      res.on('finish', () => {
        logApiCall({ tenantId, keyId: _co_keyId, apiId: 'customer_outstanding', method: 'GET',
          statusCode: res.statusCode, durationMs: Date.now() - _co_start,
          isTryIt: req.headers['x-try-it'] === '1' });
      });

      // ── 2. Load all active vendors for this tenant ──
      const allVendors = await db.select().from(vendors)
        .where(and(eq(vendors.tenantId, tenantId), eq(vendors.recordStatus, 1)));

      // Build parent → children map for roll-up logic
      const childrenByParentId = new Map<string, typeof allVendors>();
      const childVendorIds = new Set<string>();
      for (const v of allVendors) {
        if (v.parentVendorId) {
          childVendorIds.add(v.id);
          if (!childrenByParentId.has(v.parentVendorId)) childrenByParentId.set(v.parentVendorId, []);
          childrenByParentId.get(v.parentVendorId)!.push(v);
        }
      }

      // Identify "shared-name groups" — vendor names used by more than one record.
      // Example: 96 HPCL records all have the same vendor_name but different ship_to_name / mobile.
      // These vendors get INDIVIDUAL entries matched by ship_to_name (not buyer_name),
      // so each outlet shows only its own invoices.
      const vendorNameCount = new Map<string, number>();
      for (const v of allVendors) {
        if (childVendorIds.has(v.id)) continue;
        const nk = (v.vendorName || '').toLowerCase().trim();
        vendorNameCount.set(nk, (vendorNameCount.get(nk) || 0) + 1);
      }
      const sharedNameGroups = new Set<string>(
        [...vendorNameCount.entries()].filter(([, c]) => c > 1).map(([n]) => n)
      );

      // ── 3. Load ALL invoices for this tenant (not just unpaid — mirrors vendor ledger) ──
      const allInvoicesRaw = await db.execute(sql`
        SELECT id, invoice_number, invoice_date, buyer_name, ship_to_name,
               total_amount, amount_received, status,
               ship_to_address, ship_to_city, ship_to_state, ship_to_pincode
        FROM invoices
        WHERE tenant_id = ${tenantId}
          AND record_status = 1
          AND status != 'cancelled'
        ORDER BY invoice_date ASC
      `);
      const allInvoicesList: any[] = allInvoicesRaw.rows || [];

      // ── 4. Load invoice_payments (actual received amounts — mirrors vendor ledger) ──
      const pmtRows = await db.execute(sql`
        SELECT invoice_id,
               SUM(CASE WHEN payment_method != 'Debit Note Adjustment' THEN amount ELSE 0 END) AS actual_paid,
               SUM(CASE WHEN payment_method  = 'Debit Note Adjustment' THEN amount ELSE 0 END) AS dn_adj
        FROM invoice_payments
        WHERE tenant_id = ${tenantId} AND record_status = 1
        GROUP BY invoice_id
      `);
      const actualPaidByInvoice = new Map<string, number>();
      const dnAdjByInvoice = new Map<string, number>();
      (pmtRows.rows || []).forEach((r: any) => {
        actualPaidByInvoice.set(r.invoice_id, Number(r.actual_paid) || 0);
        dnAdjByInvoice.set(r.invoice_id, Number(r.dn_adj) || 0);
      });

      // ── 5. Load credit notes & debit notes ──
      const cnRows = await db.execute(sql`
        SELECT invoice_id, SUM(grand_total) AS total
        FROM credit_notes
        WHERE tenant_id = ${tenantId} AND record_status = 1 AND status = 'issued'
        GROUP BY invoice_id
      `);
      const dnRows = await db.execute(sql`
        SELECT invoice_id, SUM(grand_total) AS total
        FROM debit_notes
        WHERE tenant_id = ${tenantId} AND record_status = 1 AND status = 'issued'
        GROUP BY invoice_id
      `);
      const creditByInvoice = new Map<string, number>();
      (cnRows.rows || []).forEach((r: any) => creditByInvoice.set(r.invoice_id, Number(r.total) || 0));
      const debitByInvoice = new Map<string, number>();
      (dnRows.rows || []).forEach((r: any) => debitByInvoice.set(r.invoice_id, Number(r.total) || 0));

      // ── 6. Load customer advances (available balance = amount - usedAmount) ──
      const advRows = await db.execute(sql`
        SELECT vendor_id, SUM(amount - COALESCE(used_amount, 0)) AS available
        FROM customer_advances
        WHERE tenant_id = ${tenantId} AND record_status = 1 AND status = 'active' AND cancelled_at IS NULL
        GROUP BY vendor_id
      `);
      const advancesByVendor = new Map<string, number>();
      (advRows.rows || []).forEach((r: any) => advancesByVendor.set(r.vendor_id, Number(r.available) || 0));

      // ── 7. Enrich every invoice with per-invoice outstanding ──
      //   Use invoice_payments as source of truth for received amount.
      //   Fallback: amount_received from invoice table if no payment records exist.
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      const enriched = allInvoicesList.map((inv: any) => {
        const total = Number(inv.total_amount) || 0;
        const creditAdj = creditByInvoice.get(inv.id) || 0;
        const debitAdj = debitByInvoice.get(inv.id) || 0;
        // Use SUM of invoice_payments as received; fall back to amount_received if no payment records
        const paidFromPayments = (actualPaidByInvoice.get(inv.id) || 0) + (dnAdjByInvoice.get(inv.id) || 0);
        const amtRcvd = Number(inv.amount_received) || 0;
        const effectiveReceived = Math.max(amtRcvd, paidFromPayments);
        const outstanding = Math.max(0, total + debitAdj - creditAdj - effectiveReceived);
        const invoiceDate = new Date(inv.invoice_date);
        const daysOld = Math.floor((today.getTime() - invoiceDate.getTime()) / 86400000);
        return {
          id: inv.id,
          invoiceNumber: inv.invoice_number,
          invoiceDate: inv.invoice_date,
          buyerName: inv.buyer_name as string,
          shipToName: (inv.ship_to_name as string) || null,
          totalAmount: total,
          outstanding,
          daysOld,
          shipToAddress: inv.ship_to_address || null,
          shipToCity: inv.ship_to_city || null,
          shipToState: inv.ship_to_state || null,
          shipToPincode: inv.ship_to_pincode || null,
        };
      });

      // ── 8. Build lookup: name (lower) → list of enriched invoices with outstanding ──
      //   An invoice belongs to a name if buyer_name OR ship_to_name matches.
      const invoicesByName = new Map<string, typeof enriched>();
      const addToName = (name: string | null | undefined, inv: typeof enriched[0]) => {
        const k = (name || '').toLowerCase().trim();
        if (!k) return;
        if (!invoicesByName.has(k)) invoicesByName.set(k, []);
        invoicesByName.get(k)!.push(inv);
      };
      for (const inv of enriched) {
        addToName(inv.buyerName, inv);
        if (inv.shipToName && inv.shipToName.toLowerCase() !== inv.buyerName?.toLowerCase()) {
          addToName(inv.shipToName, inv);
        }
      }

      // ── 9. Apply business rules per vendor ──
      // Vendors with a UNIQUE name → processed once, matched by vendorName OR shipToName.
      // Vendors in a SHARED-NAME group (e.g. 96 HPCL records) → each processed individually,
      // matched by shipToName only (their own delivery point), so each outlet shows its own invoices.
      const seenVendorNames = new Set<string>(); // used only for unique-name vendors
      const results: any[] = [];

      for (const vendor of allVendors) {
        if (childVendorIds.has(vendor.id)) continue; // rolled up under parent

        const nameKey = (vendor.vendorName || '').toLowerCase().trim();
        const isSharedName = sharedNameGroups.has(nameKey);

        if (!isSharedName) {
          // Unique-name vendor: deduplicate (belt-and-suspenders guard)
          if (seenVendorNames.has(nameKey)) continue;
          seenVendorNames.add(nameKey);
        }

        // Build invoice name-keys for this vendor
        const children = childrenByParentId.get(vendor.id) || [];
        const hasChildren = children.length > 0;

        let nameKeys: string[];
        if (isSharedName) {
          // Shared-name vendor (e.g. HPCL outlet): only match by their specific ship_to_name.
          // Using buyer_name would pull ALL sibling outlets' invoices.
          nameKeys = [(vendor as any).shipToName]
            .filter(Boolean)
            .map((n: string) => n.toLowerCase().trim());
        } else {
          // Unique-name vendor: match by vendorName OR shipToName, plus any children
          nameKeys = [
            vendor.vendorName,
            (vendor as any).shipToName,
            ...children.map(c => c.vendorName),
            ...children.map(c => (c as any).shipToName),
          ]
            .filter(Boolean)
            .map((n: string) => n.toLowerCase().trim());
        }

        // Collect invoices (deduplicate by invoice id — an invoice might match on both buyer and ship_to)
        const seen = new Set<string>();
        const vendorInvoices: typeof enriched = [];
        const childNames = new Set<string>();
        for (const key of nameKeys) {
          for (const inv of invoicesByName.get(key) || []) {
            if (!seen.has(inv.id)) {
              seen.add(inv.id);
              vendorInvoices.push(inv);
              // Track which child name this invoice came from
              const childMatch = children.find(c =>
                c.vendorName?.toLowerCase() === key || (c as any).shipToName?.toLowerCase() === key
              );
              if (childMatch) childNames.add(childMatch.vendorName || '');
            }
          }
        }

        // Only consider invoices that have a balance > 0
        const outstandingInvoices = vendorInvoices.filter(i => i.outstanding > 0);
        if (outstandingInvoices.length === 0) continue;

        // Customer advances for this vendor family
        const familyAdvances = [vendor.id, ...children.map(c => c.id)]
          .reduce((s, id) => s + (advancesByVendor.get(id) || 0), 0);

        // Apply bill-to-bill / COD rules
        const paymentMode = (vendor as any).paymentMode || 'bill_to_bill';
        let includedInvoices: typeof outstandingInvoices;
        let latestInvoiceExcluded = false;
        let allIncludedDueToOverdue = false;

        if (paymentMode === 'cod') {
          includedInvoices = outstandingInvoices;
        } else {
          const sorted = [...outstandingInvoices].sort(
            (a, b) => new Date(b.invoiceDate).getTime() - new Date(a.invoiceDate).getTime()
          );
          const anyOverdue = sorted.some(inv => inv.daysOld > 30);
          if (anyOverdue) {
            includedInvoices = outstandingInvoices;
            allIncludedDueToOverdue = true;
          } else {
            includedInvoices = sorted.slice(1); // exclude latest (current cycle)
            latestInvoiceExcluded = true;
          }
        }

        // pendingAmountPaise = sum of included invoice outstandings minus advances
        const grossPaise = includedInvoices.reduce((s, i) => s + i.outstanding, 0);
        const pendingAmountPaise = Math.max(0, grossPaise - familyAdvances);

        // HP Retail detection
        const isHpRetail = outstandingInvoices.some(i => (i.buyerName || '').toUpperCase().includes('HPCL'));
        let shippingAddress: Record<string, string | null> | null = null;
        if (isHpRetail) {
          const sortedAll = [...outstandingInvoices].sort(
            (a, b) => new Date(b.invoiceDate).getTime() - new Date(a.invoiceDate).getTime()
          );
          const withShip = sortedAll.find(i => i.shipToAddress || i.shipToName);
          if (withShip) {
            shippingAddress = {
              name: withShip.shipToName,
              address: withShip.shipToAddress,
              city: withShip.shipToCity,
              state: withShip.shipToState,
              pincode: withShip.shipToPincode,
            };
          }
        }

        const childNameList = [...childNames];
        // For shared-name vendors (e.g. HPCL outlets), show the dealer's own name as outletName.
        const vendorShipToName = (vendor as any).shipToName || null;
        const entry: any = {
          vendorId: vendor.id,
          vendorCode: vendor.vendorCode,
          // For shared-name vendors customerName is the company name; outletName is the specific dealer
          customerName: vendor.vendorName,
          ...(isSharedName && vendorShipToName && { outletName: vendorShipToName }),
          mobileNumber: vendor.mobileNumber || '',
          paymentMode,
          isHpRetail,
          hasChildren,
          ...(hasChildren && childNameList.length > 0 && { childAccountNames: childNameList }),
          invoiceCount: includedInvoices.length,
          totalOutstandingInvoices: outstandingInvoices.length,
          pendingAmountRupees: parseFloat((pendingAmountPaise / 100).toFixed(2)),
          advancesAppliedRupees: parseFloat((Math.min(grossPaise, familyAdvances) / 100).toFixed(2)),
          latestInvoiceExcluded,
          allIncludedDueToOverdue,
          invoices: includedInvoices.map(i => ({
            invoiceNumber: i.invoiceNumber,
            invoiceDate: i.invoiceDate,
            sourceAccount: i.buyerName,
            outstandingRupees: parseFloat((i.outstanding / 100).toFixed(2)),
            daysOld: i.daysOld,
          })),
        };
        if (isHpRetail && shippingAddress) entry.shippingAddress = shippingAddress;
        results.push(entry);
      }

      // Sort by pending amount descending
      results.sort((a, b) => b.pendingAmountRupees - a.pendingAmountRupees);

      res.json({
        timestamp: new Date().toISOString(),
        tenantId,
        totalCustomers: results.length,
        totalPendingRupees: parseFloat(results.reduce((s, r) => s + r.pendingAmountRupees, 0).toFixed(2)),
        customers: results,
      });
    } catch (err) {
      console.error('[External API] customer-outstanding error:', err);
      res.status(500).json({ error: 'Internal Server Error', message: 'Failed to compute outstanding' });
    }
  });

  // ──────────────────────────────────────────────────────────────────────────
  // POST /api/external/allocate-cash-sales
  // Authorization: Bearer <api_key>  OR  authenticated session
  //
  // Marks cash-mode invoices as paid by creating invoice_payments records.
  //
  // Body (JSON):
  //   customer   (string, required) — exact or partial buyer_name match (case-insensitive)
  //   from_date  (string, required) — YYYY-MM-DD  invoice_date range start (inclusive)
  //   to_date    (string, required) — YYYY-MM-DD  invoice_date range end   (inclusive)
  //   dry_run    (boolean, optional, default false) — preview without writing to DB
  //   remarks    (string, optional) — note attached to each created payment record
  //
  // Logic:
  //   1. Find all invoices where payment_mode = 'Cash' (case-insensitive)
  //      AND buyer_name ILIKE %customer%
  //      AND invoice_date BETWEEN from_date AND to_date
  //      AND record_status = 1 AND status != 'cancelled'
  //   2. For each invoice, compute outstanding = total_amount - SUM(invoice_payments.amount)
  //   3. If outstanding > 0 → create an invoice_payment record (unless dry_run=true)
  //   4. Returns: allocated[], skipped[], summary totals
  //
  // All amounts in RUPEES (₹) — paise ÷ 100
  // ──────────────────────────────────────────────────────────────────────────
  app.post('/api/external/allocate-cash-sales', async (req: any, res) => {
    try {
      const _acs_start = Date.now();
      let _acs_keyId: string | undefined;
      // ── 1. Authenticate ──
      let tenantId: number;
      let callerUserId: string | null = null;
      const authHeader = req.headers['authorization'] || '';
      const rawKey = authHeader.startsWith('Bearer ') ? authHeader.slice(7).trim() : '';

      if (rawKey) {
        const keyHash = crypto.createHash('sha256').update(rawKey).digest('hex');
        const keyRows = await db.execute(sql`
          SELECT id, tenant_id, scopes FROM external_api_keys
          WHERE key_hash = ${keyHash} AND is_active = 1 LIMIT 1
        `);
        const keyRecord = (keyRows.rows as any[])[0];
        if (!keyRecord) {
          return res.status(401).json({ error: 'Unauthorized', message: 'Invalid or revoked API key' });
        }
        const keyScopes: string[] | null = keyRecord.scopes ? JSON.parse(keyRecord.scopes) : null;
        if (keyScopes && !keyScopes.includes('allocate_cash_sales')) {
          return res.status(403).json({ error: 'Forbidden', message: 'This API key does not have access to allocate_cash_sales. Update the key scopes in API Keys settings.' });
        }
        db.execute(sql`UPDATE external_api_keys SET last_used_at = NOW() WHERE id = ${keyRecord.id}`).catch(() => {});
        tenantId = keyRecord.tenant_id;
        _acs_keyId = String(keyRecord.id);
      } else if (req.isAuthenticated && req.isAuthenticated()) {
        tenantId = req.user?.tenantId;
        callerUserId = req.user?.id || null;
        if (!tenantId) return res.status(401).json({ error: 'Unauthorized' });
      } else {
        return res.status(401).json({ error: 'Unauthorized', message: 'Missing Authorization: Bearer <key> header' });
      }

      // Register call-logging on response finish
      res.on('finish', () => {
        logApiCall({ tenantId, keyId: _acs_keyId, apiId: 'allocate_cash_sales', method: 'POST',
          statusCode: res.statusCode, durationMs: Date.now() - _acs_start,
          isTryIt: req.headers['x-try-it'] === '1' });
      });

      // ── 2. Validate inputs ──
      const { customer, from_date, to_date, dry_run = false, remarks } = req.body;

      if (!customer || typeof customer !== 'string' || customer.trim() === '') {
        return res.status(400).json({
          error: 'Bad Request',
          message: '`customer` is required — provide the customer/buyer name',
        });
      }
      if (!from_date || !to_date) {
        return res.status(400).json({
          error: 'Bad Request',
          message: '`from_date` and `to_date` are required (YYYY-MM-DD)',
        });
      }
      const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
      if (!dateRegex.test(from_date) || !dateRegex.test(to_date)) {
        return res.status(400).json({
          error: 'Bad Request',
          message: '`from_date` and `to_date` must be in YYYY-MM-DD format',
        });
      }
      if (from_date > to_date) {
        return res.status(400).json({
          error: 'Bad Request',
          message: '`from_date` must be on or before `to_date`',
        });
      }
      const isDryRun = dry_run === true || dry_run === 'true';

      // ── 3. Fetch cash-mode invoices for the customer in date range ──
      const cashInvoicesRaw = await db.execute(sql`
        SELECT id, invoice_number, invoice_date, buyer_name, total_amount, amount_received, status
        FROM invoices
        WHERE tenant_id = ${tenantId}
          AND record_status = 1
          AND status != 'cancelled'
          AND LOWER(TRIM(payment_mode)) = 'cash'
          AND LOWER(buyer_name) LIKE LOWER(${`%${customer.trim()}%`})
          AND invoice_date BETWEEN ${from_date}::date AND ${to_date}::date
        ORDER BY invoice_date ASC, invoice_number ASC
      `);
      const cashInvoices: any[] = cashInvoicesRaw.rows || [];

      if (cashInvoices.length === 0) {
        return res.status(200).json({
          success: true,
          dryRun: isDryRun,
          message: `No cash-mode invoices found for customer matching "${customer}" between ${from_date} and ${to_date}.`,
          summary: { invoicesFound: 0, invoicesAllocated: 0, invoicesSkipped: 0, totalAllocatedRupees: 0 },
          allocated: [],
          skipped: [],
        });
      }

      // ── 4. Fetch existing payments for these invoices ──
      const invoiceIds = cashInvoices.map((inv: any) => inv.id);
      const existingPaymentsRaw = await db.execute(sql`
        SELECT invoice_id, SUM(amount) AS total_paid
        FROM invoice_payments
        WHERE tenant_id = ${tenantId}
          AND record_status = 1
          AND invoice_id = ANY(${sql.raw(`ARRAY['${invoiceIds.join("','")}']::varchar[]`)})
        GROUP BY invoice_id
      `);
      const paidByInvoice = new Map<string, number>();
      (existingPaymentsRaw.rows || []).forEach((r: any) => {
        paidByInvoice.set(r.invoice_id, Number(r.total_paid) || 0);
      });

      // ── 5. Process each invoice ──
      const allocated: any[] = [];
      const skipped: any[] = [];
      const bulkAllocationId = `CASH-${format(new Date(), 'yyyyMMdd-HHmmss')}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`;
      const paymentDate = new Date().toISOString();

      for (const inv of cashInvoices) {
        const totalPaid = paidByInvoice.get(inv.id) || 0;
        const outstanding = Number(inv.total_amount) - totalPaid;

        if (outstanding <= 0) {
          skipped.push({
            invoiceId: inv.id,
            invoiceNumber: inv.invoice_number,
            invoiceDate: inv.invoice_date,
            buyerName: inv.buyer_name,
            totalAmountRupees: parseFloat((Number(inv.total_amount) / 100).toFixed(2)),
            alreadyPaidRupees: parseFloat((totalPaid / 100).toFixed(2)),
            reason: 'Already fully paid',
          });
          continue;
        }

        // Create payment record unless dry_run
        if (!isDryRun) {
          await db.execute(sql`
            INSERT INTO invoice_payments (
              invoice_id, payment_date, amount, payment_method, payment_type,
              paid_by, payer_name, remarks, bulk_allocation_id, recorded_by, tenant_id
            ) VALUES (
              ${inv.id},
              ${paymentDate},
              ${outstanding},
              'Cash',
              ${outstanding >= Number(inv.total_amount) ? 'Full' : 'Partial'},
              'buyer',
              ${inv.buyer_name},
              ${remarks || `Cash sale allocation via API (${from_date} to ${to_date})`},
              ${bulkAllocationId},
              ${callerUserId},
              ${tenantId}
            )
          `);
          // Update invoice.amount_received
          await db.execute(sql`
            UPDATE invoices
            SET amount_received = amount_received + ${outstanding},
                updated_at = NOW()
            WHERE id = ${inv.id} AND tenant_id = ${tenantId}
          `);
        }

        allocated.push({
          invoiceId: inv.id,
          invoiceNumber: inv.invoice_number,
          invoiceDate: inv.invoice_date,
          buyerName: inv.buyer_name,
          totalAmountRupees: parseFloat((Number(inv.total_amount) / 100).toFixed(2)),
          alreadyPaidRupees: parseFloat((totalPaid / 100).toFixed(2)),
          allocatedRupees: parseFloat((outstanding / 100).toFixed(2)),
          paymentType: outstanding >= Number(inv.total_amount) ? 'Full' : 'Partial',
        });
      }

      const totalAllocatedPaise = allocated.reduce((s, a) => s + Math.round(a.allocatedRupees * 100), 0);

      res.json({
        success: true,
        dryRun: isDryRun,
        bulkAllocationId: isDryRun ? null : bulkAllocationId,
        message: isDryRun
          ? `Dry run: ${allocated.length} invoice(s) would be marked as paid (₹${(totalAllocatedPaise / 100).toFixed(2)}). Pass dry_run: false to apply.`
          : `${allocated.length} invoice(s) marked as paid (₹${(totalAllocatedPaise / 100).toFixed(2)}).`,
        summary: {
          invoicesFound: cashInvoices.length,
          invoicesAllocated: allocated.length,
          invoicesSkipped: skipped.length,
          totalAllocatedRupees: parseFloat((totalAllocatedPaise / 100).toFixed(2)),
        },
        allocated,
        skipped,
      });

    } catch (err) {
      console.error('[External API] allocate-cash-sales error:', err);
      res.status(500).json({ error: 'Internal Server Error', message: 'Failed to allocate cash sales' });
    }
  });

  // ─── Super-admin: Cross-tenant security API ──────────────────────────────────

  function requireSuperAdmin(req: any, res: any, next: any) {
    if (!req.isAuthenticated() || !req.user?.isSuperAdmin) {
      return res.status(403).json({ message: 'Super-admin access required' });
    }
    next();
  }


  // Dynamic external API router — handles all UI-registered custom APIs
  // POST /api/external/kinto-distributor-lead
  app.options('/api/external/kinto-distributor-lead', (req: any, res: any) => {
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Authorization, Content-Type');
    res.sendStatus(204);
  });

  app.post('/api/external/kinto-distributor-lead', async (req: any, res: any) => {
    res.setHeader('Access-Control-Allow-Origin', '*');
    try {
      const authHeader = req.headers['authorization'] || '';
      const rawKey = authHeader.startsWith('Bearer ') ? authHeader.slice(7).trim() : '';
      if (!rawKey) {
        return res.status(401).json({ error: 'Unauthorized', message: 'Missing Authorization: Bearer <key> header' });
      }
      const keyHash = crypto.createHash('sha256').update(rawKey).digest('hex');
      const keyRows = await db.execute(sql`
        SELECT id, tenant_id, scopes FROM external_api_keys
        WHERE key_hash = ${keyHash} AND is_active = 1 LIMIT 1
      `);
      const keyRecord = keyRows.rows[0] as any;
      if (!keyRecord) {
        return res.status(401).json({ error: 'Unauthorized', message: 'Invalid or revoked API key' });
      }
      db.execute(sql`UPDATE external_api_keys SET last_used_at = NOW() WHERE id = ${keyRecord.id}`).catch(() => {});
      const tenantId = keyRecord.tenant_id;
      const { name, phone, company, product_interest, source, status, notes, email } = req.body;
      if (!name || !phone) {
        return res.status(400).json({ error: 'Bad Request', message: 'name and phone are required' });
      }
      const cntRows = await db.execute(sql`SELECT COUNT(*) as cnt FROM crm_leads WHERE tenant_id = ${tenantId}`);
      const cnt = Number((cntRows.rows[0] as any)?.cnt || 0) + 1;
      const leadNo = 'LEAD-' + String(cnt).padStart(4, '0');
      const result = await db.execute(sql`
        INSERT INTO crm_leads (tenant_id, lead_no, name, phone, company, product_interest, source, status, notes, email)
        VALUES (
          ${tenantId}, ${leadNo}, ${name}, ${phone},
          ${company ?? null},
          ${product_interest ?? 'Kinto Water Distributorship'},
          ${source ?? 'Kinto Distributor Ad'},
          ${status ?? 'new'},
          ${notes ?? ('Applied via Kinto Distributor Ad. Tier: ' + (product_interest ?? '') + '. District: ' + (company ?? ''))},
          ${email ?? null}
        )
        RETURNING id, lead_no
      `);
      return res.status(201).json({ success: true, lead_no: (result.rows[0] as any).lead_no, id: (result.rows[0] as any).id });
    } catch (e: any) {
      return res.status(500).json({ error: 'Internal Server Error', message: e.message });
    }
  });

  // Dynamic external API router — handles all UI-registered custom APIs
  app.use('/api/pdf', pdfRouter);

  // ── i18n: persist tenant default locale (en/hi/te/ar) ────────────────────
  app.put('/api/i18n/locale', async (req: any, res) => {
    try {
      if (!req.isAuthenticated?.() && !req.user) return res.status(401).json({ message: 'Unauthorized' });
      const tenantId = req.session?.tenantId ?? req.user?.tenantId ?? 1;
      const { locale } = req.body;
      const SUPPORTED = ['en','hi','te','ta','bn','ar','es','fr','de','pt','zh','ja','ru','id'];
      if (!SUPPORTED.includes(locale)) return res.status(400).json({ message: 'Invalid locale' });
      await db.execute(sql`ALTER TABLE tenant_settings ADD COLUMN IF NOT EXISTS default_locale VARCHAR(5) DEFAULT 'en'`);
      await db.execute(sql`UPDATE tenant_settings SET default_locale = ${locale} WHERE tenant_id = ${tenantId}`);
      res.json({ success: true, locale });
    } catch (e: any) { res.status(500).json({ message: e.message }); }
  });
  app.get('/api/i18n/locale', async (req: any, res) => {
    try {
      const tenantId = req.session?.tenantId ?? req.user?.tenantId ?? 1;
      await db.execute(sql`ALTER TABLE tenant_settings ADD COLUMN IF NOT EXISTS default_locale VARCHAR(5) DEFAULT 'en'`);
      const r = await db.execute(sql`SELECT default_locale FROM tenant_settings WHERE tenant_id = ${tenantId} LIMIT 1`);
      res.json({ locale: (r.rows[0] as any)?.default_locale || 'en' });
    } catch (e: any) { res.json({ locale: 'en' }); }
  });

  // ── i18n: tenant-configurable translation overrides (custom terms per locale) ──
  const ensureI18nOverrides = () => db.execute(sql`CREATE TABLE IF NOT EXISTS i18n_overrides (
    id SERIAL PRIMARY KEY, tenant_id INT NOT NULL,
    locale VARCHAR(5) NOT NULL, tkey VARCHAR(100) NOT NULL, tvalue TEXT NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE (tenant_id, locale, tkey)
  )`);
  app.get('/api/i18n/overrides', async (req: any, res) => {
    try {
      const tenantId = req.session?.tenantId ?? req.user?.tenantId ?? 1;
      const locale = String(req.query.locale || 'en');
      await ensureI18nOverrides();
      const r = await db.execute(sql`SELECT tkey, tvalue FROM i18n_overrides WHERE tenant_id = ${tenantId} AND locale = ${locale}`);
      const overrides: Record<string, string> = {};
      for (const row of r.rows as any[]) overrides[row.tkey] = row.tvalue;
      res.json({ locale, overrides });
    } catch (e: any) { res.json({ locale: req.query.locale, overrides: {} }); }
  });
  app.put('/api/i18n/overrides', async (req: any, res) => {
    try {
      if (!req.isAuthenticated?.() && !req.user) return res.status(401).json({ message: 'Unauthorized' });
      const tenantId = req.session?.tenantId ?? req.user?.tenantId ?? 1;
      const { locale, overrides } = req.body; // overrides: { key: value }
      if (!locale || typeof overrides !== 'object') return res.status(400).json({ message: 'locale and overrides required' });
      await ensureI18nOverrides();
      for (const [k, v] of Object.entries(overrides)) {
        if (v === null || v === '') {
          await db.execute(sql`DELETE FROM i18n_overrides WHERE tenant_id = ${tenantId} AND locale = ${locale} AND tkey = ${k}`);
        } else {
          await db.execute(sql`INSERT INTO i18n_overrides (tenant_id, locale, tkey, tvalue) VALUES (${tenantId}, ${locale}, ${k}, ${String(v)})
            ON CONFLICT (tenant_id, locale, tkey) DO UPDATE SET tvalue = EXCLUDED.tvalue, updated_at = NOW()`);
        }
      }
      res.json({ success: true, count: Object.keys(overrides).length });
    } catch (e: any) { res.status(500).json({ message: e.message }); }
  });

  // ── Vertical Notification API ────────────────────────────────────────────
  // POST /api/notifications/send — send a one-off vertical notification
  app.post('/api/notifications/send', async (req: any, res) => {
    if (!req.isAuthenticated?.() && !req.user) return res.status(401).json({ error: 'Unauthorized' });
    const { type, payload } = req.body;
    const tid: number = req.session?.tenantId ?? req.user?.tenantId ?? 1;
    try {
      switch (type) {
        case 'hotel_checkin_confirmation':
          await verticalNotificationService.sendCheckinConfirmation({ ...payload, tenantId: tid });
          break;
        case 'restaurant_order_status':
          await verticalNotificationService.sendOrderStatusUpdate(payload);
          break;
        default:
          return res.status(400).json({ error: `Unknown notification type: ${type}` });
      }
      res.json({ success: true, type });
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

