  // PATCH /api/user/password — change own password with policy enforcement
  app.patch('/api/user/password', async (req: any, res) => {
    if (!req.isAuthenticated()) return res.status(401).json({ message: 'Unauthorized' });
    const { currentPassword, newPassword } = req.body;
    if (!currentPassword || !newPassword) return res.status(400).json({ message: 'Current and new passwords are required' });

    const validation = validatePasswordStrength(newPassword);
    if (!validation.valid) return res.status(400).json({ message: validation.errors.join(' '), errors: validation.errors });

    try {
      const user = req.user as any;
      const row = await pool.query('SELECT password, password_history FROM users WHERE id = $1', [user.id]);
      const dbUser = row.rows[0];
      if (!dbUser) return res.status(404).json({ message: 'User not found' });

      const validCurrent = await comparePasswords(currentPassword, dbUser.password);
      if (!validCurrent) return res.status(400).json({ message: 'Current password is incorrect' });

      const inHistory = await isPasswordInHistory(newPassword, dbUser.password_history ?? []);
      if (inHistory) return res.status(400).json({ message: 'You cannot reuse any of your last 5 passwords.' });

      const hashed = await hashPassword(newPassword);
      const newHistory = [...(dbUser.password_history ?? []).slice(-4), hashed];

      await pool.query(
        'UPDATE users SET password = $1, password_history = $2, password_changed_at = NOW(), must_change_password = false WHERE id = $3',
        [hashed, newHistory, user.id]
      );
      res.json({ message: 'Password changed successfully' });
    } catch (err) {
      res.status(500).json({ message: 'Failed to change password' });
    }
  });

  // ─── Admin: List users for a tenant (super-admin only) ───────
  app.get('/api/admin/tenants/:tenantId/users', async (req: any, res) => {
    if (!req.isAuthenticated() || !req.user?.isSuperAdmin) return res.status(403).json({ message: 'Super-admin only' });
    const tenantId = parseInt(req.params.tenantId);
    if (isNaN(tenantId)) return res.status(400).json({ message: 'Invalid tenant ID' });
    try {
      // users table has no is_active column — active users are identified by record_status = 1
      // user IDs are UUIDs (text), not integers
      const { rows } = await pool.query(
        `SELECT id, username, email, role, record_status AS "isActive" FROM users WHERE tenant_id = $1 AND record_status = 1 ORDER BY role, username`,
        [tenantId]
      );
      res.json(rows);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // ─── Admin: Reset any tenant user's password (super-admin only) ───────────
  app.post('/api/admin/tenants/:tenantId/users/:userId/reset-password', async (req: any, res) => {
    if (!req.isAuthenticated() || !req.user?.isSuperAdmin) return res.status(403).json({ message: 'Super-admin only' });
    const tenantId = parseInt(req.params.tenantId);
    const userId   = req.params.userId; // UUID string — do NOT parseInt
    const { newPassword } = req.body as { newPassword: string };
    if (isNaN(tenantId)) return res.status(400).json({ message: 'Invalid tenant ID' });
    if (!userId) return res.status(400).json({ message: 'Invalid user ID' });
    if (!newPassword || newPassword.length < 6) return res.status(400).json({ message: 'Password must be at least 6 characters' });
    try {
      const { rows } = await pool.query(
        `SELECT id FROM users WHERE id = $1 AND tenant_id = $2 AND record_status = 1`,
        [userId, tenantId]
      );
      if (rows.length === 0) return res.status(404).json({ message: 'User not found in this tenant' });
      const hashed = await hashPassword(newPassword);
      await pool.query(
        `UPDATE users SET password = $1, password_changed_at = NOW(), must_change_password = true WHERE id = $2`,
        [hashed, userId]
      );
      res.json({ message: 'Password reset successfully. User will be prompted to change it on next login.' });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });


  // ─── Thermal print proxy (for network ESC/POS printers) ──────────────────
  app.post('/api/print/thermal', async (req: any, res) => {
    if (!req.isAuthenticated()) return res.status(401).json({ message: 'Unauthorized' });
    const { ip, port, html } = req.body;
    if (!ip || !port) return res.status(400).json({ message: 'ip and port are required' });
    // For now return success — full ESC/POS encoding is complex and
    // the window.print() fallback works for most thermal printer setups.
    // In production: use net.Socket to send ESC/POS bytes to the printer.
    try {
      const net = await import('net');
      const socket = new net.Socket();
      await new Promise<void>((resolve, reject) => {
        const timeout = setTimeout(() => { socket.destroy(); reject(new Error('Printer timeout')); }, 3000);
        socket.connect(Number(port), ip, () => {
          clearTimeout(timeout);
          // Send a minimal ESC/POS receipt with the bill number extracted from html
          const text = html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 500);
          socket.write(Buffer.from('\x1B\x40' + text + '\n\n\n\x1D\x56\x41\x00', 'utf8'));
          socket.end();
          resolve();
        });
        socket.on('error', (err) => { clearTimeout(timeout); reject(err); });
      });
      res.json({ success: true });
    } catch (err: any) {
      // Non-fatal — client falls back to window.print()
      res.json({ success: false, message: err.message });
    }
  });

