      const r = await db.execute(sql`UPDATE logistics_eway_bills SET valid_upto=${newValid}, vehicle_no=COALESCE(${new_vehicle_no||null},vehicle_no) WHERE id=${req.params.id} AND tenant_id=${t} RETURNING *`);
